import hashlib,json,sys,tarfile,os
MANIFEST_TEXT = '{\n  "files": [\n    {\n      "path": "t25-player-lock-consumer/clear-helper.receipt.json",\n      "sha256": "e9c3aee7bbcd5bb404c0b69b8756674bb4fb14c4fd3a4d86a6f6628c8036411f",\n      "bytes": 431\n    },\n    {\n      "path": "t25-player-lock-consumer/clear-helper.stderr",\n      "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",\n      "bytes": 0\n    },\n    {\n      "path": "t25-player-lock-consumer/clear-helper.stdout",\n      "sha256": "b25d734bdfe7e48ca3e91ec49ccb0b0dd6a0657544296b89951d68bffb23a1af",\n      "bytes": 7373\n    },\n    {\n      "path": "t25-player-lock-consumer/configure.receipt.json",\n      "sha256": "eb455a8d1306596a1abf844c8d952703dda6b6860f5bb02203e4d1a824fec156",\n      "bytes": 431\n    },\n    {\n      "path": "t25-player-lock-consumer/configure.stderr",\n      "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",\n      "bytes": 0\n    },\n    {\n      "path": "t25-player-lock-consumer/configure.stdout",\n      "sha256": "4f355860e4785b792be84a8a92e33ff98ffe73b7495ab819d94a517c2a70cb85",\n      "bytes": 39334\n    },\n    {\n      "path": "t25-player-lock-consumer/drawPicture.llvm.stdout",\n      "sha256": "5d90d100cc4989af1c9f53c2672356ef48190a47c5d6e117434161505b2cb6e5",\n      "bytes": 44067\n    },\n    {\n      "path": "t25-player-lock-consumer/drawPicture.pseudocode.txt",\n      "sha256": "9f711b3caaaf487574ba3a41f05283514918377c9019cdf63ced4b7c9014f0be",\n      "bytes": 15359\n    },\n    {\n      "path": "t25-player-lock-consumer/drawPicture.receipt.json",\n      "sha256": "0e5a765257494c4d3332c52807a68dbb66e3f97e28631db3e22f0fb96bbd8d55",\n      "bytes": 478\n    },\n    {\n      "path": "t25-player-lock-consumer/drawPicture_FUN_002f977c.evidence.json",\n      "sha256": "43b3f227e5f3e35cd265ea0a0a66e18372745a0be26701cb0220e7f4180a3100",\n      "bytes": 36007\n    },\n    {\n      "path": "t25-player-lock-consumer/geometry-plt.stdout",\n      "sha256": "4c2b6afdbdb57a79b375bd24194f0027d12af30f802f4e350bae1034a7d0893a",\n      "bytes": 399\n    },\n    {\n      "path": "t25-player-lock-consumer/input.json",\n      "sha256": "d5c55dff4452c34a38740fe28f8277d0d191b73a8698f60a576166879fa0cb28",\n      "bytes": 251\n    },\n    {\n      "path": "t25-player-lock-consumer/lock-plt.stdout",\n      "sha256": "63caca05d5c078df4fc2709ca93d395c567dbb0cd8dce24aec0358d256c383bc",\n      "bytes": 389\n    },\n    {\n      "path": "t25-player-lock-consumer/relocations.stdout",\n      "sha256": "bd285e33ca50118dabffe1f284e06e36c4cbc506ec2638637c6a977c2e2b3fba",\n      "bytes": 1577431\n    },\n    {\n      "path": "t25-player-lock-consumer/results-v1.json",\n      "sha256": "8826ce753b10fa5c926a42e2ce23a35459b7b67cf75ee3f4deba92f92950e4b0",\n      "bytes": 7562\n    },\n    {\n      "path": "t25-player-lock-consumer/runtime-excerpt.json",\n      "sha256": "133075b2d3d43dc69857e98695e52bac5c539f9b61c15680f557b3c0d2635d92",\n      "bytes": 3340\n    },\n    {\n      "path": "t25-player-lock-consumer/unlock-plt.stdout",\n      "sha256": "6f5278477dd81f99dce7a7e4b514fa6ea93bd9ff677f2a6472b15cb5af77c0d1",\n      "bytes": 389\n    },\n    {\n      "path": "t25-player-lock-consumer/public/README.md",\n      "sha256": "8171d0ae1da5005d08a75f6d55426b25fae09ff46ef15c0828d1dcbaf1335384",\n      "bytes": 2211\n    },\n    {\n      "path": "t25-player-lock-consumer/public/results.json",\n      "sha256": "bb73adaab4c9f2b9729de0e2abe572d5ed84518c2072b35269e3cb12c991abda",\n      "bytes": 10019\n    }\n  ]\n}\n'
archive,expected,size,manifest_sha,count=sys.argv[1:]
assert hashlib.sha256(MANIFEST_TEXT.encode()).hexdigest()==manifest_sha
with open(archive,'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==expected
assert os.stat(archive).st_size==int(size)
pins={r['path']:r for r in json.loads(MANIFEST_TEXT)['files']}
with tarfile.open(archive,'r:gz') as t:
 entries=t.getmembers();assert len(entries)==int(count)==len(pins)
 assert {e.name for e in entries}==set(pins)
 for e in entries:
  p=pins[e.name];assert e.isfile() and e.size==p['bytes']
  assert hashlib.sha256(t.extractfile(e).read()).hexdigest()==p['sha256']
print(json.dumps({'status':'ARCHIVE_AND_ALL_MEMBERS_VERIFIED','sha256':expected,'bytes':int(size),'members':len(pins),'external_member_manifest_sha256':manifest_sha}))
